--
-- Name: audit_log_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM tenants WHERE id = OLD.tenant_id) THEN
    RETURN OLD;  -- allow cascade when the tenant itself is removed
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.actor_user_id IS NULL AND OLD.actor_user_id IS NOT NULL
     AND (to_jsonb(NEW) - 'actor_user_id') = (to_jsonb(OLD) - 'actor_user_id') THEN
    RETURN NEW;  -- allow ON DELETE SET NULL when a user row is removed
  END IF;
  RAISE EXCEPTION 'audit_log is append-only';
END;
$$;

--
-- Name: log_booking_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_booking_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO booking_status_history (tenant_id, booking_id, from_status, to_status, actor_type, actor_user_id)
    VALUES (NEW.tenant_id, NEW.id,
            CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END,
            NEW.status,
            COALESCE(NULLIF(current_setting('bb.actor_type', true), ''), 'system'),
            NULLIF(current_setting('bb.actor_user_id', true), '')::uuid);
  END IF;
  RETURN NULL;
END;
$$;

--
-- Name: sync_booking_paid_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_booking_paid_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  b_id uuid := COALESCE(NEW.booking_id, OLD.booking_id);
  paid numeric(12,2);
  refunded numeric(12,2);
BEGIN
  SELECT COALESCE(SUM(amount) FILTER (WHERE kind = 'payment'), 0),
         COALESCE(SUM(amount) FILTER (WHERE kind = 'refund'), 0)
    INTO paid, refunded
    FROM booking_payments WHERE booking_id = b_id;

  UPDATE bookings
     SET advance_paid_amount = paid - refunded,
         advance_status = CASE
           WHEN refunded > 0 AND paid - refunded <= 0 THEN 'refunded'
           WHEN paid - refunded >= advance_amount AND paid - refunded > 0 THEN 'paid'
           WHEN paid - refunded > 0 THEN 'partial'
           ELSE 'pending' END
   WHERE id = b_id;
  RETURN NULL;
END;
$$;

