    CONSTRAINT themes_key_check CHECK ((key ~ '^[a-z0-9_]{2,50}$'::text))
);

--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    role_id uuid NOT NULL,
    full_name text NOT NULL,
    email text NOT NULL,
    phone text,
    password_hash text,
    is_active boolean DEFAULT true NOT NULL,
    last_login_at timestamp with time zone,
    password_changed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT users_email_check CHECK (((email = lower(email)) AND (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text))),
    CONSTRAINT users_phone_check CHECK (((phone IS NULL) OR (phone ~ '^[1-9][0-9]{7,14}$'::text)))
);

--
-- Name: webhook_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    source text DEFAULT 'whatsapp'::text NOT NULL,
    event_key text NOT NULL,
    event_type text NOT NULL,
    phone_number_id text,
    payload jsonb NOT NULL,
    signature_valid boolean NOT NULL,
    status text DEFAULT 'received'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    error_message text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT webhook_events_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT webhook_events_source_check CHECK ((source = ANY (ARRAY['whatsapp'::text, 'gdrive'::text, 'payment'::text]))),
    CONSTRAINT webhook_events_status_check CHECK ((status = ANY (ARRAY['received'::text, 'queued'::text, 'processing'::text, 'processed'::text, 'failed'::text, 'ignored'::text])))
);

--
-- Name: whatsapp_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    display_phone text NOT NULL,
    display_name text,
    phone_number_id text NOT NULL,
    waba_id text NOT NULL,
    access_token_enc text,
    status text DEFAULT 'pending'::text NOT NULL,
    is_primary boolean DEFAULT true NOT NULL,
    read_receipts_enabled boolean DEFAULT true NOT NULL,
    last_health_check_at timestamp with time zone,
    last_health_status jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whatsapp_accounts_display_phone_check CHECK ((display_phone ~ '^[1-9][0-9]{7,14}$'::text)),
    CONSTRAINT whatsapp_accounts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'connected'::text, 'disconnected'::text, 'error'::text])))
);

